insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('oats_banana_pb','Avena con plátano, yogur y crema de cacahuate','Oats with banana, yogurt and peanut butter',array['breakfast']::text[],10,array['Cuece la avena con agua (unas 2 partes de agua por 1 de avena) de 3 a 5 minutos.','Retira del fuego, añade el plátano en rodajas y la canela.','Sirve con el yogur griego encima y la crema de cacahuate.']::text[],array['Cook the oats in water (about 2 parts water to 1 part oats) for 3–5 minutes.','Remove from heat, add sliced banana and cinnamon.','Top with the Greek yogurt and the peanut butter.']::text[],'Canela al gusto','Cinnamon to taste',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
