insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('chicken_rice_broccoli','Pollo con arroz y brócoli','Chicken with rice and broccoli',array['main']::text[],25,array['Cuece el arroz (peso en seco) con el doble de agua, unos 18 minutos.','Sazona el pollo y cocínalo en la mitad del aceite hasta 74 °C (165 °F) en el centro.','Cuece el brócoli al vapor 5 minutos y rocía el aceite restante.']::text[],array['Cook the rice (dry weight) in twice its volume of water, about 18 minutes.','Season the chicken and cook it in half the oil to an internal 165 °F (74 °C).','Steam the broccoli for 5 minutes and drizzle with the remaining oil.']::text[],'Sal, ajo en polvo, pimentón y limón','Salt, garlic powder, paprika and lemon',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
