insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('salmon_potato_greenbeans','Salmón con papa y ejotes','Salmon with potato and green beans',array['main']::text[],30,array['Hornea la papa en cubos a 200 °C (400 °F) por 25 minutos con la mitad del aceite.','Hornea el salmón sazonado de 12 a 15 minutos en la misma bandeja.','Cuece los ejotes al vapor 6 minutos.']::text[],array['Roast the diced potato at 400 °F (200 °C) for 25 minutes with half the oil.','Bake the seasoned salmon for 12–15 minutes on the same tray.','Steam the green beans for 6 minutes.']::text[],'Sal, eneldo, limón y pimienta','Salt, dill, lemon and pepper',false) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
