insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('beef_pasta_tomato','Pasta con carne molida y salsa de jitomate','Pasta with ground beef and tomato sauce',array['main']::text[],25,array['Cuece la pasta (peso en seco) según el empaque.','Sofríe la cebolla y el ajo en el aceite, añade la carne y dórala bien.','Agrega el jitomate picado y las hierbas; cocina 10 minutos y mezcla con la pasta.']::text[],array['Cook the pasta (dry weight) according to the package.','Sauté onion and garlic in the oil, add the beef and brown it well.','Add chopped tomato and herbs; simmer 10 minutes and toss with the pasta.']::text[],'Ajo, orégano, albahaca y sal','Garlic, oregano, basil and salt',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
