insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('turkey_tacos','Tacos de pavo con verduras','Turkey tacos with vegetables',array['main']::text[],20,array['Cocina el pavo con las especias en un sartén antiadherente hasta que no quede rosado.','Calienta las tortillas.','Arma los tacos con la lechuga, el jitomate y el aguacate.']::text[],array['Cook the turkey with the spices in a non-stick pan until no longer pink.','Warm the tortillas.','Assemble with lettuce, tomato and avocado.']::text[],'Comino, chile en polvo, sal, cilantro y limón','Cumin, chili powder, salt, cilantro and lime',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
