insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('quinoa_chickpea_bowl','Bowl de quinoa con garbanzos y verduras','Quinoa bowl with chickpeas and vegetables',array['main']::text[],20,array['Enjuaga la quinoa y cuécela con el doble de agua 15 minutos.','Pica el pepino y el jitomate.','Mezcla todo con los garbanzos, el aceite, el limón y las especias.']::text[],array['Rinse the quinoa and simmer it in twice its volume of water for 15 minutes.','Dice the cucumber and tomato.','Toss everything with the chickpeas, oil, lemon and seasoning.']::text[],'Limón, sal, pimienta y perejil','Lemon, salt, pepper and parsley',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
