insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('lentil_stew_rice','Lentejas guisadas con arroz','Lentil stew with rice',array['main']::text[],30,array['Sofríe la cebolla, el ajo y la zanahoria en el aceite 5 minutos.','Añade las lentejas cocidas, especias y un poco de agua; cocina 15 minutos.','Sirve con el arroz cocido (peso indicado en seco).']::text[],array['Sauté onion, garlic and carrot in the oil for 5 minutes.','Add the cooked lentils, spices and a splash of water; simmer 15 minutes.','Serve with the cooked rice (weight given as dry).']::text[],'Ajo, comino, laurel y sal','Garlic, cumin, bay leaf and salt',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
