insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('tilapia_sweetpotato_spinach','Tilapia con camote y espinaca','Tilapia with sweet potato and spinach',array['main']::text[],25,array['Hornea el camote en cubos a 200 °C (400 °F) por 25 minutos.','Cocina la tilapia sazonada en la mitad del aceite 3–4 minutos por lado.','Saltea la espinaca con el aceite restante 1 minuto.']::text[],array['Roast the diced sweet potato at 400 °F (200 °C) for 25 minutes.','Pan-cook the seasoned tilapia in half the oil, 3–4 minutes per side.','Wilt the spinach in the remaining oil for 1 minute.']::text[],'Ajo, limón, sal y pimentón','Garlic, lemon, salt and paprika',false) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
