insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('shrimp_rice_stirfry','Camarones salteados con arroz y verduras','Shrimp stir-fry with rice and vegetables',array['main']::text[],20,array['Cuece el arroz (peso en seco).','Saltea las verduras en el aceite a fuego alto 4 minutos.','Añade los camarones y cocina 2–3 minutos hasta que estén rosados y opacos.']::text[],array['Cook the rice (dry weight).','Stir-fry the vegetables in the oil over high heat for 4 minutes.','Add the shrimp and cook 2–3 minutes until pink and opaque.']::text[],'Ajo, jengibre, limón y sal','Garlic, ginger, lime and salt',false) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
