insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('tempeh_rice_broccoli','Tempeh salteado con arroz y brócoli','Tempeh stir-fry with rice and broccoli',array['main']::text[],20,array['Cuece el arroz (peso en seco).','Corta el tempeh en cubos y dóralo en el aceite 6 minutos.','Añade el brócoli y los condimentos; saltea 4 minutos más.']::text[],array['Cook the rice (dry weight).','Cube the tempeh and brown it in the oil for 6 minutes.','Add the broccoli and seasonings; stir-fry 4 more minutes.']::text[],'Ajo, jengibre y salsa de soya baja en sodio (contiene soya y trigo)','Garlic, ginger and low-sodium soy sauce (contains soy and wheat)',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
