insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('tofu_quinoa_stirfry','Tofu salteado con quinoa y verduras','Tofu stir-fry with quinoa and vegetables',array['main']::text[],25,array['Enjuaga la quinoa y cuécela con el doble de agua 15 minutos.','Seca el tofu con papel, córtalo en cubos y dóralo en el aceite 8 minutos.','Añade las verduras y saltea 4 minutos; sirve sobre la quinoa.']::text[],array['Rinse the quinoa and simmer it in twice its volume of water for 15 minutes.','Pat the tofu dry, cube it and brown it in the oil for 8 minutes.','Add the vegetables, stir-fry 4 minutes and serve over the quinoa.']::text[],'Ajo, jengibre, limón y sal','Garlic, ginger, lime and salt',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
