insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('pork_sweetpotato_carrot','Lomo de cerdo con camote y zanahoria','Pork tenderloin with sweet potato and carrot',array['main']::text[],35,array['Hornea el camote y la zanahoria en cubos con la mitad del aceite a 200 °C (400 °F), 25 minutos.','Sella el lomo en el aceite restante y termina en el horno hasta 63 °C (145 °F) en el centro.','Deja reposar la carne 3 minutos antes de rebanar.']::text[],array['Roast the diced sweet potato and carrot with half the oil at 400 °F (200 °C) for 25 minutes.','Sear the tenderloin in the remaining oil and finish in the oven to an internal 145 °F (63 °C).','Rest the meat for 3 minutes before slicing.']::text[],'Romero, ajo, sal y pimienta','Rosemary, garlic, salt and pepper',true) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
