insert into public.recipes (id,name_es,name_en,meal_types,prep_minutes,steps_es,steps_en,seasonings_es,seasonings_en,batch_friendly) values ('beans_rice_egg','Frijoles negros con arroz, huevo y aguacate','Black beans with rice, egg and avocado',array['main']::text[],15,array['Cuece el arroz (peso en seco) y calienta los frijoles con comino.','Cocina los huevos y las claras a tu gusto en sartén antiadherente.','Sirve con aguacate, salsa y cilantro.']::text[],array['Cook the rice (dry weight) and warm the beans with cumin.','Cook the eggs and whites your way in a non-stick pan.','Serve with avocado, salsa and cilantro.']::text[],'Salsa, cilantro, sal y comino','Salsa, cilantro, salt and cumin',false) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, steps_es = excluded.steps_es, steps_en = excluded.steps_en, updated_at = now();
