insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('back_squat','Sentadilla con barra','Barbell back squat','squat','quads',array['glutes','core','lower_back']::text[],array['barbell']::text[],'barbell',3,true,array['knee','lower_back']::text[],array['Barra apoyada en la parte alta de la espalda, pies al ancho de hombros.','Baja controlando con el pecho alto y rodillas en la dirección de los pies.','Sube empujando el suelo y manteniendo la espalda neutra.']::text[],array['Bar on the upper back, feet shoulder-width apart.','Descend under control, chest up, knees tracking over toes.','Drive up through the floor keeping a neutral spine.']::text[],array['Redondear la zona lumbar en la parte baja.','Dejar que las rodillas se vayan hacia dentro.']::text[],array['Rounding the lower back at the bottom.','Letting the knees cave inward.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('goblet_squat','Sentadilla goblet con mancuerna','Dumbbell goblet squat','squat','quads',array['glutes','core']::text[],array['dumbbell']::text[],'dumbbell',1,true,array['knee']::text[],array['Sostén la mancuerna vertical frente al pecho.','Baja entre las piernas con el torso erguido.','Sube sin perder la posición de los codos.']::text[],array['Hold the dumbbell upright at your chest.','Sit down between your legs with an upright torso.','Stand up keeping elbows in position.']::text[],array['Despegar los talones del suelo.','Inclinar el torso hacia delante en exceso.']::text[],array['Lifting the heels.','Leaning the torso too far forward.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('leg_press','Prensa de piernas','Leg press','squat','quads',array['glutes','hamstrings']::text[],array['machine']::text[],'machine',1,true,array['knee']::text[],array['Espalda y cadera pegadas al respaldo.','Baja hasta donde la pelvis no se despegue.','Empuja sin bloquear las rodillas de golpe.']::text[],array['Keep back and hips against the pad.','Lower only as far as your pelvis stays down.','Press without snapping the knees locked.']::text[],array['Bajar tanto que la pelvis se enrolla.','Bloquear las rodillas con violencia.']::text[],array['Going so deep the pelvis tucks.','Violently locking the knees.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('bodyweight_squat','Sentadilla con peso corporal','Bodyweight squat','squat','quads',array['glutes']::text[],array['bodyweight']::text[],'bodyweight',1,true,array['knee']::text[],array['Pies al ancho de hombros, brazos al frente para equilibrio.','Baja controlado hasta una profundidad cómoda.','Sube con el peso repartido en todo el pie.']::text[],array['Feet shoulder-width, arms forward for balance.','Lower under control to a comfortable depth.','Stand with weight spread over the whole foot.']::text[],array['Rebotar abajo.','Rodillas hacia dentro.']::text[],array['Bouncing at the bottom.','Knees caving in.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('romanian_deadlift','Peso muerto rumano con barra','Barbell Romanian deadlift','hinge','hamstrings',array['glutes','lower_back']::text[],array['barbell']::text[],'barbell',2,true,array['lower_back']::text[],array['Rodillas ligeramente flexionadas y fijas.','Lleva la cadera atrás deslizando la barra pegada a las piernas.','Sube apretando glúteos sin hiperextender la espalda.']::text[],array['Knees slightly bent and fixed.','Push the hips back sliding the bar along the legs.','Stand by squeezing the glutes without over-arching.']::text[],array['Redondear la espalda.','Convertirlo en una sentadilla doblando mucho las rodillas.']::text[],array['Rounding the back.','Turning it into a squat by bending the knees too much.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('db_romanian_deadlift','Peso muerto rumano con mancuernas','Dumbbell Romanian deadlift','hinge','hamstrings',array['glutes','lower_back']::text[],array['dumbbell']::text[],'dumbbell',1,true,array['lower_back']::text[],array['Mancuernas frente a los muslos.','Cadera atrás con la espalda neutra hasta sentir los isquiotibiales.','Vuelve arriba empujando la cadera al frente.']::text[],array['Dumbbells in front of the thighs.','Hips back with a neutral spine until you feel the hamstrings.','Return by driving the hips forward.']::text[],array['Bajar más allá de lo que permite la espalda neutra.','Alejar las mancuernas del cuerpo.']::text[],array['Going lower than a neutral back allows.','Letting the dumbbells drift away.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('kb_swing','Balanceo con kettlebell','Kettlebell swing','hinge','glutes',array['hamstrings','core']::text[],array['kettlebell']::text[],'kettlebell',2,true,array['lower_back']::text[],array['Movimiento de cadera, no de brazos.','Lleva la pesa entre las piernas y extiende la cadera con fuerza.','Tronco firme arriba, como en una plancha de pie.']::text[],array['Hip-driven, not arm-driven.','Hike the bell back and snap the hips forward.','Brace at the top like a standing plank.']::text[],array['Hacer una sentadilla en lugar de bisagra.','Levantar con los brazos o hiperextender la espalda.']::text[],array['Squatting instead of hinging.','Lifting with the arms or leaning back at the top.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('band_good_morning','Buenos días con banda','Band good morning','hinge','hamstrings',array['glutes','lower_back']::text[],array['bands']::text[],'band',1,true,array['lower_back']::text[],array['Pisa la banda y pásala por detrás del cuello sobre los hombros.','Inclina el tronco llevando la cadera atrás.','Vuelve arriba apretando glúteos.']::text[],array['Stand on the band and loop it behind your neck over the shoulders.','Hinge forward pushing the hips back.','Return by squeezing the glutes.']::text[],array['Redondear la espalda.','Usar una banda demasiado tensa al inicio.']::text[],array['Rounding the back.','Using a band that is too heavy at first.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('db_reverse_lunge','Zancada hacia atrás con mancuernas','Dumbbell reverse lunge','lunge','quads',array['glutes','hamstrings']::text[],array['dumbbell']::text[],'dumbbell',1,true,array['knee']::text[],array['Da un paso atrás y baja la rodilla trasera cerca del suelo.','El peso va en el pie delantero.','Regresa empujando con el talón delantero.']::text[],array['Step back and lower the back knee toward the floor.','Keep weight on the front foot.','Return by pushing through the front heel.']::text[],array['Paso demasiado corto.','Perder el equilibrio por mirar abajo.']::text[],array['Taking too short a step.','Losing balance by looking down.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('bulgarian_split_squat','Sentadilla búlgara','Bulgarian split squat','lunge','quads',array['glutes']::text[],array['dumbbell','bench']::text[],'dumbbell',2,true,array['knee']::text[],array['Empeine trasero sobre el banco.','Baja vertical sobre la pierna delantera.','Sube con el torso estable.']::text[],array['Rear foot laces on the bench.','Lower straight down over the front leg.','Rise with a stable torso.']::text[],array['Pie delantero demasiado cerca del banco.','Empujar con la pierna trasera.']::text[],array['Front foot too close to the bench.','Pushing with the back leg.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('bw_reverse_lunge','Zancada hacia atrás con peso corporal','Bodyweight reverse lunge','lunge','quads',array['glutes']::text[],array['bodyweight']::text[],'bodyweight',1,true,array['knee']::text[],array['Paso atrás controlado.','Rodilla trasera cerca del suelo sin golpearlo.','Regresa empujando con la pierna delantera.']::text[],array['Controlled step back.','Back knee near the floor without hitting it.','Return pushing through the front leg.']::text[],array['Inclinar el torso hacia delante.','Rodilla delantera hacia dentro.']::text[],array['Leaning the torso forward.','Front knee caving in.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('step_up','Subida al banco con mancuernas','Dumbbell step-up','lunge','quads',array['glutes']::text[],array['dumbbell','bench']::text[],'dumbbell',1,true,array['knee']::text[],array['Coloca todo el pie en el banco.','Sube empujando con la pierna de arriba.','Baja despacio sin dejarte caer.']::text[],array['Place the whole foot on the bench.','Drive up with the top leg.','Lower slowly without dropping.']::text[],array['Impulsarse con la pierna de abajo.','Usar un banco demasiado alto.']::text[],array['Pushing off the bottom leg.','Using a box that is too high.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('bench_press','Press de banca con barra','Barbell bench press','h_push','chest',array['triceps','front_delts']::text[],array['barbell','bench']::text[],'barbell',2,true,array['shoulder','wrist']::text[],array['Escápulas juntas y hacia abajo, pies firmes.','Baja la barra a la parte media del pecho con los codos a unos 45–70°.','Empuja hacia arriba y ligeramente hacia atrás. Usa ayudante o topes de seguridad.']::text[],array['Shoulder blades pinched down, feet planted.','Lower the bar to mid-chest with elbows at about 45–70°.','Press up and slightly back. Use a spotter or safety pins.']::text[],array['Rebotar la barra en el pecho.','Codos completamente abiertos a 90°.']::text[],array['Bouncing the bar off the chest.','Flaring elbows to 90°.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('db_bench_press','Press de banca con mancuernas','Dumbbell bench press','h_push','chest',array['triceps','front_delts']::text[],array['dumbbell','bench']::text[],'dumbbell',1,true,array['shoulder']::text[],array['Escápulas retraídas sobre el banco.','Baja las mancuernas a los lados del pecho.','Sube juntándolas ligeramente arriba.']::text[],array['Shoulder blades retracted on the bench.','Lower the dumbbells beside the chest.','Press up bringing them slightly together.']::text[],array['Bajar demasiado y forzar el hombro.','Perder el control arriba.']::text[],array['Lowering too far and straining the shoulder.','Losing control at the top.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('incline_db_press','Press inclinado con mancuernas','Incline dumbbell press','h_push','chest',array['front_delts','triceps']::text[],array['dumbbell','bench']::text[],'dumbbell',1,true,array['shoulder']::text[],array['Banco a 30–45°.','Baja controlado hacia la parte alta del pecho.','Empuja sin arquear en exceso.']::text[],array['Bench at 30–45°.','Lower under control toward the upper chest.','Press without excessive arching.']::text[],array['Banco demasiado vertical (se vuelve press de hombro).','Despegar la cadera.']::text[],array['Bench too upright (turns into a shoulder press).','Lifting the hips.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('machine_chest_press','Press de pecho en máquina','Machine chest press','h_push','chest',array['triceps','front_delts']::text[],array['machine']::text[],'machine',1,true,array['shoulder']::text[],array['Ajusta el asiento: agarres a la altura del pecho medio.','Empuja sin despegar la espalda.','Regresa lento.']::text[],array['Set the seat so handles are at mid-chest.','Press without lifting your back off the pad.','Return slowly.']::text[],array['Asiento mal ajustado.','Soltar el peso de golpe.']::text[],array['Seat set at the wrong height.','Letting the weight crash back.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('push_up','Flexiones de brazos','Push-up','h_push','chest',array['triceps','front_delts','core']::text[],array['bodyweight']::text[],'bodyweight',1,true,array['wrist','shoulder']::text[],array['Cuerpo en línea recta de cabeza a talones.','Baja el pecho entre las manos con codos a unos 45°.','Si cuesta, apoya las manos en una superficie elevada.']::text[],array['Body in a straight line from head to heels.','Lower your chest between your hands with elbows at about 45°.','If too hard, elevate your hands on a sturdy surface.']::text[],array['Dejar caer la cadera.','Hacer repeticiones a medias.']::text[],array['Sagging hips.','Doing half reps.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('overhead_press','Press militar con barra','Barbell overhead press','v_push','front_delts',array['triceps','side_delts','core']::text[],array['barbell']::text[],'barbell',3,true,array['shoulder','lower_back']::text[],array['Glúteos y abdomen firmes.','Empuja la barra en línea recta pasando la cara.','Termina con la barra sobre la mitad del pie.']::text[],array['Glutes and abs braced.','Press the bar straight up past your face.','Finish with the bar over mid-foot.']::text[],array['Arquear la zona lumbar.','Empujar la barra hacia delante.']::text[],array['Arching the lower back.','Pressing the bar forward.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('db_shoulder_press','Press de hombro con mancuernas','Dumbbell shoulder press','v_push','front_delts',array['triceps','side_delts']::text[],array['dumbbell']::text[],'dumbbell',1,true,array['shoulder']::text[],array['Mancuernas a la altura de los hombros.','Empuja hacia arriba sin chocar las pesas.','Baja controlado.']::text[],array['Dumbbells at shoulder height.','Press up without clashing them.','Lower under control.']::text[],array['Arquear la espalda.','Bajar demasiado rápido.']::text[],array['Arching the back.','Lowering too fast.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('machine_shoulder_press','Press de hombro en máquina','Machine shoulder press','v_push','front_delts',array['triceps','side_delts']::text[],array['machine']::text[],'machine',1,true,array['shoulder']::text[],array['Agarres a la altura de los hombros.','Empuja sin bloquear de golpe.','Espalda apoyada.']::text[],array['Handles at shoulder height.','Press without slamming into lockout.','Back supported.']::text[],array['Asiento demasiado bajo.','Rebote abajo.']::text[],array['Seat too low.','Bouncing at the bottom.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('pike_push_up','Flexión en pica','Pike push-up','v_push','front_delts',array['triceps']::text[],array['bodyweight']::text[],'bodyweight',2,true,array['shoulder','wrist']::text[],array['Cadera alta formando una V invertida.','Baja la cabeza entre las manos.','Empuja de vuelta manteniendo la cadera alta.']::text[],array['Hips high in an inverted V.','Lower your head between your hands.','Press back keeping hips high.']::text[],array['Convertirlo en flexión normal.','Golpear la cabeza en el suelo.']::text[],array['Turning it into a regular push-up.','Hitting the head on the floor.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('band_overhead_press','Press de hombro con banda','Band overhead press','v_push','front_delts',array['triceps','side_delts']::text[],array['bands']::text[],'band',1,true,array['shoulder']::text[],array['Pisa la banda con ambos pies.','Empuja hacia arriba con el abdomen firme.','Baja despacio.']::text[],array['Stand on the band with both feet.','Press up with abs braced.','Lower slowly.']::text[],array['Arquear la espalda.','Soltar la tensión de golpe.']::text[],array['Arching the back.','Letting the band snap back.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('barbell_row','Remo con barra','Barbell row','h_pull','upper_back',array['lats','biceps','lower_back']::text[],array['barbell']::text[],'barbell',2,true,array['lower_back']::text[],array['Torso inclinado a unos 45° con espalda neutra.','Lleva la barra hacia el ombligo.','Baja con control.']::text[],array['Torso at about 45° with a neutral back.','Row the bar toward your belly button.','Lower under control.']::text[],array['Usar impulso del torso.','Redondear la espalda.']::text[],array['Using torso momentum.','Rounding the back.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('one_arm_db_row','Remo a una mano con mancuerna','One-arm dumbbell row','h_pull','lats',array['upper_back','biceps']::text[],array['dumbbell','bench']::text[],'dumbbell',1,true,'{}'::text[],array['Mano y rodilla apoyadas en el banco.','Lleva la mancuerna hacia la cadera.','Baja estirando sin girar el torso.']::text[],array['Hand and knee on the bench.','Pull the dumbbell toward your hip.','Lower fully without twisting.']::text[],array['Girar el torso para subir más peso.','Encoger el hombro.']::text[],array['Twisting the torso to lift more.','Shrugging the shoulder.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('seated_cable_row','Remo sentado en polea','Seated cable row','h_pull','upper_back',array['lats','biceps']::text[],array['cable']::text[],'cable',1,true,'{}'::text[],array['Pecho alto y espalda neutra.','Lleva el agarre al abdomen juntando escápulas.','Regresa sin redondear la espalda.']::text[],array['Chest up, neutral back.','Pull the handle to your abdomen squeezing the shoulder blades.','Return without rounding.']::text[],array['Balancear el torso.','Tirar sólo con los brazos.']::text[],array['Rocking the torso.','Pulling only with the arms.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('chest_supported_row','Remo con pecho apoyado en máquina','Chest-supported machine row','h_pull','upper_back',array['lats','rear_delts','biceps']::text[],array['machine']::text[],'machine',1,true,'{}'::text[],array['Pecho apoyado en el soporte.','Tira con los codos hacia atrás.','Pausa breve con escápulas juntas.']::text[],array['Chest on the pad.','Drive the elbows back.','Brief pause with shoulder blades squeezed.']::text[],array['Despegar el pecho del soporte.','Recorrido corto.']::text[],array['Lifting the chest off the pad.','Short range of motion.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('band_row','Remo con banda','Band row','h_pull','upper_back',array['lats','biceps']::text[],array['bands']::text[],'band',1,true,'{}'::text[],array['Ancla la banda a la altura del pecho.','Tira llevando los codos atrás.','Regresa despacio.']::text[],array['Anchor the band at chest height.','Pull driving the elbows back.','Return slowly.']::text[],array['Anclaje inseguro.','Encoger hombros.']::text[],array['Insecure anchor.','Shrugging.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('pull_up','Dominadas','Pull-up','v_pull','lats',array['biceps','upper_back']::text[],array['pullup_bar']::text[],'bodyweight',3,true,array['shoulder','elbow']::text[],array['Agarre algo más ancho que los hombros.','Sube llevando el pecho hacia la barra.','Baja hasta extender los brazos con control. Usa banda de asistencia si hace falta.']::text[],array['Grip slightly wider than shoulders.','Pull your chest toward the bar.','Lower to full extension under control. Use an assistance band if needed.']::text[],array['Balancearse.','Hacer medias repeticiones.']::text[],array['Kipping/swinging.','Half reps.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
