insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('band_pulldown','Jalón con banda','Band pulldown','v_pull','lats',array['biceps']::text[],array['bands']::text[],'band',1,true,'{}'::text[],array['Ancla la banda en un punto alto y seguro.','Lleva los codos hacia las costillas.','Regresa despacio.']::text[],array['Anchor the band high and secure.','Drive the elbows to your ribs.','Return slowly.']::text[],array['Anclaje inseguro.','Tirar con impulso.']::text[],array['Insecure anchor.','Using momentum.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
insert into public.exercises (id,name_es,name_en,pattern,primary_muscle,secondary_muscles,equipment,load_type,difficulty,compound,stress_areas,cues_es,cues_en,mistakes_es,mistakes_en) values ('lying_leg_curl','Curl femoral en máquina','Machine leg curl','knee_flex','hamstrings','{}'::text[],array['machine']::text[],'machine',1,false,array['knee']::text[],array['Rodillas alineadas con el eje de la máquina.','Flexiona hasta el máximo cómodo.','Baja lento.']::text[],array['Knees aligned with the machine pivot.','Curl to your comfortable end range.','Lower slowly.']::text[],array['Levantar la cadera.','Bajar de golpe.']::text[],array['Lifting the hips.','Dropping the weight.']::text[]) on conflict (id) do update set name_es = excluded.name_es, name_en = excluded.name_en, cues_es = excluded.cues_es, cues_en = excluded.cues_en, mistakes_es = excluded.mistakes_es, mistakes_en = excluded.mistakes_en, updated_at = now();
